import sys

def main():
    import sys
    a, b, c, d = map(int, sys.stdin.read().strip().split())

    # Check if it's possible to form a beautiful sequence
    if abs(a - b) > 1 or abs(b - c) > 1 or abs(c - d) > 1:
        print("NO")
        return

    # Try to construct the sequence
    sequence = []
    current = 0
    counts = [a, b, c, d]

    while sum(counts) > 0:
        if counts[current] == 0:
            current += 1
            continue
        sequence.append(current)
        counts[current] -= 1
        if current == 0:
            if counts[1] > counts[2]:
                current = 1
            else:
                current = 2
        elif current == 3:
            if counts[2] > counts[1]:
                current = 2
            else:
                current = 1
        else:
            if counts[current - 1] >= counts[current + 1]:
                current -= 1
            else:
                current += 1

    print("YES")
    print(" ".join(map(str, sequence)))

if __name__ == "__main__":
    main()
